+/**
+ * Sanitize Block Editor content to prevent XSS attacks
+ * Removes dangerous HTML elements and attributes that could be used for XSS
+ */
+
+export function sanitizeBlockEditorContent(data: any): any {
+	if (!data) return data;
+
+	if (Array.isArray(data)) {
+		return data.map(item => sanitizeBlockEditorContent(item));
+	}
+
+	if (typeof data === 'object' && data !== null) {
+		const sanitized: any = {};
+
+		for (const [key, value] of Object.entries(data)) {
+			// Check if this looks like Block Editor content
+			if (key === 'content' || key === 'data' || key === 'blocks') {
+				sanitized[key] = sanitizeBlockEditorContent(value);
+			} else if (typeof value === 'string') {
+				// Sanitize string values that might contain HTML
+				sanitized[key] = sanitizeHtmlString(value);
+			} else if (typeof value === 'object' && value !== null) {
+				sanitized[key] = sanitizeBlockEditorContent(value);
+			} else {
+				sanitized[key] = value;
+			}
+		}
+
+		return sanitized;
+	}
+
+	if (typeof data === 'string') {
+		return sanitizeHtmlString(data);
+	}
+
+	return data;
+}
+
+function sanitizeHtmlString(str: string): string {
+	if (typeof str !== 'string') return str;
+
+	// Remove iframe elements with srcdoc attribute (XSS vector)
+	str = str.replace(/<iframe[^>]*srcdoc[^>]*>[\s\S]*?<\/iframe>/gi, '');
+	// Remove script tags
+	str = str.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
+	// Remove event handlers
+	str = str.replace(/\s+on\w+\s*=\s*["'][^"']*["']/gi, '');
+
+	return str;
+}

