+/**
+ * Validates domain strings to prevent injection attacks
+ */
+export function isValidDomain(domain: string): boolean {
+  if (typeof domain !== 'string' || domain.length === 0) {
+    return false
+  }
+  
+  // Domain must not contain invalid characters
+  // Allow alphanumeric, dots, hyphens, and wildcards for subdomains
+  const domainRegex = /^(\*\.)?([a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)*[a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?$/
+  
+  if (!domainRegex.test(domain)) {
+    return false
+  }
+  
+  // Ensure domain length is within reasonable bounds
+  if (domain.length > 253) {
+    return false
+  }
+  
+  return true
+}
+
+/**
+ * Validates remote pattern objects
+ */
+export function isValidRemotePattern(pattern: any): boolean {
+  if (typeof pattern !== 'object' || pattern === null) {
+    return false
+  }
+  
+  const { protocol, hostname } = pattern
+  
+  return typeof protocol === 'string' && typeof hostname === 'string' && 
+         isValidDomain(hostname) && /^https?$/.test(protocol)
+}

