+/**
+ * Validates that a URL is safe to fetch from (public IP, safe protocol)
+ * Prevents SSRF attacks by blocking:
+ * - Private/reserved IP addresses
+ * - Non-HTTP(S) protocols
+ * - file://, data://, and other unsafe schemes
+ */
+
+const PRIVATE_IP_RANGES = [
+  // Loopback
+  /^127\./,
+  /^::1$/,
+  /^::ffff:127\./,
+  // Private networks
+  /^10\./,
+  /^172\.(1[6-9]|2[0-9]|3[01])\./,
+  /^192\.168\./,
+  /^::ffff:10\./,
+  /^::ffff:172\.(1[6-9]|2[0-9]|3[01])\./,
+  /^::ffff:192\.168\./,
+  // Link-local
+  /^169\.254\./,
+  /^fe80:/i,
+  /^::ffff:169\.254\./,
+  // Multicast
+  /^224\./,
+  /^ff00:/i,
+  // Broadcast
+  /^255\.255\.255\.255$/,
+  // This network
+  /^0\./,
+  // Documentation/examples
+  /^192\.0\.2\./,
+  /^198\.51\.100\./,
+  /^203\.0\.113\./,
+];
+
+const RESERVED_HOSTNAMES = new Set([
+  "localhost",
+  "localhost.localdomain",
+  "invalid",
+  "example",
+  "example.com",
+  "example.net",
+  "example.org",
+  "test",
+  "test.example",
+]);
+
+/**
+ * Check if an IP address is private or reserved
+ */
+function isPrivateIp(ip: string): boolean {
+  // Normalize IPv6
+  const normalizedIp = ip.toLowerCase();
+  
+  for (const pattern of PRIVATE_IP_RANGES) {
+    if (pattern.test(normalizedIp)) {
+      return true;
+    }
+  }
+  
+  return false;
+}
+
+/**
+ * Resolve hostname to IP and check if it's public
+ */
+async function isPublicHostname(hostname: string): Promise<boolean> {
+  // Check reserved hostnames
+  if (RESERVED_HOSTNAMES.has(hostname.toLowerCase())) {
+    return false;
+  }
+  
+  try {
+    // Try to resolve the hostname
+    const response = await fetch(`https://dns.google/resolve?name=${encodeURIComponent(hostname)}&type=A`, {
+      method: "GET",
+    });
+    
+    if (!response.ok) {
+      return false;
+    }
+    
+    const data = await response.json() as { Answer?: Array<{ data: string }> };
+    const answers = data.Answer || [];
+    
+    for (const answer of answers) {
+      if (isPrivateIp(answer.data)) {
+        return false;
+      }
+    }
+    
+    return answers.length > 0;
+  } catch {
+    // If DNS resolution fails, reject the URL
+    return false;
+  }
+}
+
+/**
+ * Validate that a URL is safe to fetch from
+ */
+export async function isPublicUrl(urlString: string): Promise<boolean> {
+  try {
+    const url = new URL(urlString);
+    
+    // Only allow HTTP and HTTPS protocols
+    if (url.protocol !== "http:" && url.protocol !== "https:") {
+      return false;
+    }
+    
+    // Ensure hostname exists
+    if (!url.hostname) {
+      return false;
+    }
+    
+    // Check if hostname is an IP address
+    const ipMatch = url.hostname.match(/^(\d+\.\d+\.\d+\.\d+|\[?[0-9a-f:]+\]?)$/i);
+    if (ipMatch) {
+      const ip = url.hostname.replace(/[\[\]]/g, "");
+      return !isPrivateIp(ip);
+    }
+    
+    // For domain names, perform DNS resolution check
+    return await isPublicHostname(url.hostname);
+  } catch {
+    // Invalid URL
+    return false;
+  }
+}

