 import { GRPC_ENCODING_HEADER, GRPC_MESSAGE_HEADER, GRPC_ACCEPT_ENCODING_HEADER } from './metadata';

 const GRPC_MESSAGE_SIZE_HEADER = 'grpc-message-size';

 export class Http2CallStream extends CallStream {
   private http2stream: http2.ServerHttp2Stream | http2.ClientHttp2Stream;
   private maxReceiveMessageLength: number;
   private maxSendMessageLength: number;
   private decompressor: zlib.Decompressor | null = null;
   private incomingMessageSize: number = 0;
   private incomingMessageBuffer: Buffer[] = [];
   private decompressedSize: number = 0;

   constructor(
     http2stream: http2.ServerHttp2Stream | http2.ClientHttp2Stream,
     maxReceiveMessageLength: number,
     maxSendMessageLength: number
   ) {
     super();
     this.http2stream = http2stream;
     this.maxReceiveMessageLength = maxReceiveMessageLength;
     this.maxSendMessageLength = maxSendMessageLength;
     this.setupDataHandler();
   }

   private setupDataHandler(): void {
     this.http2stream.on('data', (data: Buffer) => {
       this.handleIncomingData(data);
     });
   }

   private handleIncomingData(data: Buffer): void {
     // Check if message size on wire exceeds limit
     if (this.maxReceiveMessageLength > 0) {
       this.incomingMessageSize += data.length;
       if (this.incomingMessageSize > this.maxReceiveMessageLength) {
         this.http2stream.destroy();
         this.emit('error', new Error(`Received message exceeds maximum size of ${this.maxReceiveMessageLength}`));
         return;
       }
     }

     this.incomingMessageBuffer.push(data);
   }

   private decompressMessage(buffer: Buffer): Buffer | null {
     const encoding = this.http2stream.headers[GRPC_ENCODING_HEADER];

     if (!encoding || encoding === 'identity') {
       return buffer;
     }

     try {
       let decompressed: Buffer;

       if (encoding === 'gzip') {
         decompressed = zlib.gunzipSync(buffer);
       } else if (encoding === 'deflate') {
         decompressed = zlib.inflateSync(buffer);
       } else {
         throw new Error(`Unknown compression encoding: ${encoding}`);
       }

       // Check decompressed size against limit
       if (this.maxReceiveMessageLength > 0 && decompressed.length > this.maxReceiveMessageLength) {
         this.http2stream.destroy();
         this.emit('error', new Error(`Decompressed message exceeds maximum size of ${this.maxReceiveMessageLength}`));
         return null;
       }

       return decompressed;
     } catch (err) {
       this.emit('error', err);
       return null;
     }
   }

   private processMessage(): void {
     if (this.incomingMessageBuffer.length === 0) {
       return;
     }

     const buffer = Buffer.concat(this.incomingMessageBuffer);
     this.incomingMessageBuffer = [];
     this.incomingMessageSize = 0;

     const decompressed = this.decompressMessage(buffer);
     if (decompressed === null) {
       return;
     }

     this.emit('message', decompressed);
   }
 }

