+import { isIP } from 'net';
+
+/**
+ * Check if a hostname/IP address is private or reserved
+ * Prevents SSRF attacks by blocking access to internal networks
+ */
+export function isPrivateIP(hostname: string): boolean {
+  // Check if it's an IP address
+  const ipVersion = isIP(hostname);
+  
+  if (ipVersion === 0) {
+    // Not an IP, try to resolve it
+    // For now, we'll be conservative and allow non-IP hostnames
+    // but this could be enhanced with DNS resolution checks
+    return false;
+  }
+
+  const parts = hostname.split('.').map(Number);
+  
+  if (parts.length !== 4) {
+    return false;
+  }
+
+  // Localhost (127.0.0.0/8)
+  if (parts[0] === 127) return true;
+  
+  // Private networks (10.0.0.0/8)
+  if (parts[0] === 10) return true;
+  
+  // Private networks (172.16.0.0/12)
+  if (parts[0] === 172 && parts[1] >= 16 && parts[1] <= 31) return true;
+  
+  // Private networks (192.168.0.0/16)
+  if (parts[0] === 192 && parts[1] === 168) return true;
+  
+  // Link-local (169.254.0.0/16)
+  if (parts[0] === 169 && parts[1] === 254) return true;
+  
+  // Multicast (224.0.0.0/4)
+  if (parts[0] >= 224 && parts[0] <= 239) return true;
+  
+  // Reserved (240.0.0.0/4)
+  if (parts[0] >= 240 && parts[0] <= 255) return true;
+  
+  return false;
+}

