@@ -0,0 +1,45 @@
+/**
+ * CSRF protection middleware for localhost mutation endpoints
+ * Validates that state-changing requests originate from loopback
+ */
+
+function isLoopbackOrigin(origin) {
+  if (!origin) return false;
+  try {
+    const url = new URL(origin);
+    const hostname = url.hostname;
+    return hostname === 'localhost' || 
+           hostname === '127.0.0.1' || 
+           hostname === '[::1]' ||
+           hostname === '::1';
+  } catch {
+    return false;
+  }
+}
+
+function csrfProtectionMiddleware(req, res, next) {
+  // Only protect mutating methods
+  const mutatingMethods = ['POST', 'PUT', 'PATCH', 'DELETE'];
+  if (!mutatingMethods.includes(req.method)) {
+    return next();
+  }
+
+  // Check Sec-Fetch-Site header (modern browsers)
+  const secFetchSite = req.get('Sec-Fetch-Site');
+  if (secFetchSite === 'cross-site') {
+    return res.status(403).json({ error: 'Cross-site requests not allowed' });
+  }
+
+  // Check Origin header
+  const origin = req.get('Origin');
+  if (origin && !isLoopbackOrigin(origin)) {
+    return res.status(403).json({ error: 'Invalid origin' });
+  }
+
+  // Check Referer header as fallback
+  const referer = req.get('Referer');
+  if (referer && !isLoopbackOrigin(referer)) {
+    return res.status(403).json({ error: 'Invalid referer' });
+  }
+
+  next();
+}
+
+module.exports = csrfProtectionMiddleware;

