+import * as path from 'path';
+import * as fs from 'fs';
+
+/**
+ * Validates that a file path is within the base directory (local-root restriction).
+ * Prevents path traversal attacks.
+ * 
+ * @param filePath - The file path to validate
+ * @param baseDir - The base directory that paths must be within
+ * @returns The resolved path if valid, null if invalid
+ */
+export function validateLocalPath(filePath: string, baseDir: string): string | null {
+  try {
+    const resolvedPath = path.resolve(filePath);
+    const resolvedBase = path.resolve(baseDir);
+    
+    // Ensure the resolved path is within the base directory
+    return resolvedPath.startsWith(resolvedBase + path.sep) || resolvedPath === resolvedBase ? resolvedPath : null;
+  } catch {
+    return null;
+  }
+}

