+/**
+ * Validates that a gateway URL is safe to connect to
+ * @param {string} url - The gateway URL to validate
+ * @returns {boolean} - True if the URL is valid, false otherwise
+ */
+export const isValidGatewayUrl = (url) => {
+  if (!url || typeof url !== 'string') {
+    return false;
+  }
+
+  try {
+    const urlObj = new URL(url);
+    // Only allow ws:// and wss:// protocols
+    if (!['ws:', 'wss:'].includes(urlObj.protocol)) {
+      return false;
+    }
+    return true;
+  } catch (e) {
+    return false;
+  }
+};

