+import type { Note, User } from '../types.js';
+
+/**
+ * Check if a note is viewable by the given user
+ * @param note The note to check
+ * @param userId The ID of the user checking visibility (optional, for current user)
+ * @returns true if the note can be viewed, false otherwise
+ */
+export function canViewNote(note: Note, userId?: string): boolean {
+	// Public notes are always viewable
+	if (note.visibility === 'public') {
+		return true;
+	}
+
+	// If no userId provided, assume we're checking for anonymous access
+	// Private notes should not be viewable
+	if (!userId) {
+		return note.visibility === 'public';
+	}
+
+	// The note author can always view their own notes
+	if (note.user?.id === userId) {
+		return true;
+	}
+
+	// Followers-only notes: only viewable by followers
+	if (note.visibility === 'followers') {
+		return note.user?.isFollowed === true;
+	}
+
+	// Direct message notes: only viewable by recipients
+	if (note.visibility === 'direct') {
+		return false; // Direct notes should not be in exports unless user is recipient
+	}
+
+	return false;
+}

