new file mode 100644
index 0000000..1111111
--- /dev/null
+++ b/src/server/middleware/host-header-validation.ts
@@ -0,0 +1,30 @@
+import { Request, Response, NextFunction } from "express";
+
+/**
+ * Middleware to validate Host header and prevent DNS rebinding attacks.
+ * Allows requests to localhost, 127.0.0.1, and ::1 (IPv6 localhost).
+ */
+export function hostHeaderValidation() {
+  return (req: Request, res: Response, next: NextFunction) => {
+    const host = req.get("host");
+
+    if (!host) {
+      res.status(400).json({ error: "Missing Host header" });
+      return;
+    }
+
+    // Extract hostname without port
+    const hostname = host.split(":")[0];
+
+    // Allow localhost, 127.0.0.1, and IPv6 localhost
+    const allowedHosts = ["localhost", "127.0.0.1", "::1", "[::1]"];
+
+    if (allowedHosts.includes(hostname)) {
+      next();
+    } else {
+      res.status(403).json({
+        error: "Invalid Host header - DNS rebinding protection enabled",
+      });
+    }
+  };
+}
