+/**
+ * Guard against accidental exposure of secret keys in error messages and logs
+ */
+
+export function secretKeyExposed(message: string): boolean {
+  // Check if message contains patterns that look like base58-encoded secret keys
+  // Secret keys are typically 88 characters of base58 when encoded
+  const base58Pattern = /^[123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz]{88}$/;
+  return base58Pattern.test(message);
+}
+
+export function sanitizeError(error: Error): Error {
+  // Prevent secret keys from being exposed in error messages
+  return new Error(error.message.replace(/[123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz]{88}/g, '[REDACTED]'));
+}

