+import { ValidationRule, ValidationContext, FieldNode, SelectionSetNode } from 'graphql';
+
+interface ComplexityOptions {
+  maxComplexity?: number;
+  maxDepth?: number;
+}
+
+const DEFAULT_MAX_COMPLEXITY = 1000;
+const DEFAULT_MAX_DEPTH = 15;
+
+export function validateQueryComplexity(options: ComplexityOptions = {}): ValidationRule {
+  const maxComplexity = options.maxComplexity ?? DEFAULT_MAX_COMPLEXITY;
+  const maxDepth = options.maxDepth ?? DEFAULT_MAX_DEPTH;
+
+  return (context: ValidationContext) => {
+    return {
+      OperationDefinition(node) {
+        const complexity = calculateComplexity(node.selectionSet, context, 0);
+        const depth = calculateDepth(node.selectionSet, context, 0);
+
+        if (complexity > maxComplexity) {
+          context.reportError(
+            new Error(
+              `Query complexity of ${complexity} exceeds maximum allowed complexity of ${maxComplexity}`
+            )
+          );
+        }
+
+        if (depth > maxDepth) {
+          context.reportError(
+            new Error(
+              `Query depth of ${depth} exceeds maximum allowed depth of ${maxDepth}`
+            )
+          );
+        }
+      },
+    };
+  };
+}
+
+function calculateComplexity(
+  selectionSet: SelectionSetNode | undefined,
+  context: ValidationContext,
+  depth: number
+): number {
+  if (!selectionSet) {
+    return 0;
+  }
+
+  let complexity = 0;
+  const fieldCounts: { [key: string]: number } = {};
+
+  for (const selection of selectionSet.selections) {
+    if (selection.kind === 'Field') {
+      const fieldName = selection.name.value;
+      fieldCounts[fieldName] = (fieldCounts[fieldName] ?? 0) + 1;
+
+      // Penalize field duplication: each duplicate adds exponential cost
+      const fieldCost = fieldCounts[fieldName] * fieldCounts[fieldName];
+      complexity += fieldCost;
+
+      // Add complexity from nested selections
+      if (selection.selectionSet) {
+        complexity += calculateComplexity(selection.selectionSet, context, depth + 1);
+      }
+    }
+  }
+
+  return complexity;
+}
+
+function calculateDepth(
+  selectionSet: SelectionSetNode | undefined,
+  context: ValidationContext,
+  currentDepth: number
+): number {
+  if (!selectionSet) {
+    return currentDepth;
+  }
+
+  let maxDepth = currentDepth;
+
+  for (const selection of selectionSet.selections) {
+    if (selection.kind === 'Field' && selection.selectionSet) {
+      const depth = calculateDepth(selection.selectionSet, context, currentDepth + 1);
+      maxDepth = Math.max(maxDepth, depth);
+    }
+  }
+
+  return maxDepth;
+}

