+
+const VALID_URI_PATTERN = /^mongodb(\+srv)?:\/\/.+/i;
+const DANGEROUS_PATTERNS = [
+  /eval\s*\(/i,
+  /function\s*\(/i,
+  /constructor\s*\(/i,
+  /__proto__/i,
+  /prototype/i,
+];
+
+/**
+ * Validate connection string input to prevent code injection
+ * @param input - The connection string to validate
+ * @returns true if input is valid, false otherwise
+ */
+export function validateConnectionStringInput(input: string): boolean {
+  // Check if input is a string
+  if (typeof input !== 'string') {
+    return false;
+  }
+
+  // Check if input matches valid MongoDB URI pattern
+  if (!VALID_URI_PATTERN.test(input)) {
+    return false;
+  }
+
+  // Check for dangerous patterns that could indicate code injection attempts
+  for (const pattern of DANGEROUS_PATTERNS) {
+    if (pattern.test(input)) {
+      return false;
+    }
+  }
+
+  return true;
+}

