+/**
+ * Sanitize credentials to prevent information disclosure
+ * Removes sensitive fields from credential objects before sending to client
+ */
+export function sanitizeCredentials(credentials: any): any {
+	if (!credentials) {
+		return credentials;
+	}
+
+	const sanitized = { ...credentials };
+	
+	// Remove sensitive fields that should never be exposed
+	const sensitiveFields = ['data', 'encryptedData', 'decryptedData', 'password', 'token', 'secret', 'apiKey', 'privateKey'];
+	
+	sensitiveFields.forEach(field => {
+		delete sanitized[field];
+	});
+
+	return sanitized;
+}

