+/**
+ * Sanitize execution data to prevent information disclosure
+ * Removes sensitive credential data from execution responses
+ */
+export function sanitizeExecutionData(execution: any): any {
+	if (!execution) {
+		return execution;
+	}
+
+	const sanitized = JSON.parse(JSON.stringify(execution));
+	
+	// Remove sensitive data from execution nodes
+	if (sanitized.data && sanitized.data.resultData && sanitized.data.resultData.runData) {
+		Object.keys(sanitized.data.resultData.runData).forEach(nodeKey => {
+			const nodeData = sanitized.data.resultData.runData[nodeKey];
+			if (Array.isArray(nodeData)) {
+				nodeData.forEach(execution => {
+					if (execution.data && execution.data.main) {
+						execution.data.main.forEach((output: any) => {
+							if (Array.isArray(output)) {
+								output.forEach(item => {
+									if (item.json && item.json.credentials) {
+										delete item.json.credentials;
+									}
+								});
+							}
+						});
+					}
+				});
+			}
+		});
+	}
+	
+	return sanitized;
+}

