+import {BasicType} from "./basicType";
+
+export class UintBigIntType extends BasicType<bigint> {
+  readonly byteLength: number;
+
+  constructor(byteLength: number) {
+    super();
+    this.byteLength = byteLength;
+  }
+
+  fromBytes(data: Uint8Array, start: number): bigint {
+    if (data.length < start + this.byteLength) {
+      throw new Error("Not enough bytes");
+    }
+    let value = 0n;
+    for (let i = 0; i < this.byteLength; i++) {
+      value = value | (BigInt(data[start + i]) << BigInt(8 * i));
+    }
+    return value;
+  }
+
+  toBytes(value: bigint): Uint8Array {
+    if (typeof value !== "bigint") {
+      throw new Error("Value must be a bigint");
+    }
+    const bytes = new Uint8Array(this.byteLength);
+    for (let i = 0; i < this.byteLength; i++) {
+      bytes[i] = Number((value >> BigInt(8 * i)) & 0xFFn);
+    }
+    return bytes;
+  }
+
+  equals(a: bigint, b: bigint): boolean {
+    return a === b;
+  }
+
+  clone(value: bigint): bigint {
+    return value;
+  }
+
+  getMaxValue(): bigint {
+    return (1n << BigInt(8 * this.byteLength)) - 1n;
+  }
+
+  getMinValue(): bigint {
+    return 0n;
+  }
+
+  isValid(value: unknown): boolean {
+    return typeof value === "bigint" && value >= 0n && value <= this.getMaxValue();
+  }
+}

