+/**
+ * A simple mutex implementation for synchronizing async operations.
+ * Ensures that only one operation can execute at a time.
+ */
+export class Mutex {
+  private _locked: boolean = false;
+  private _waitQueue: Array<() => void> = [];
+
+  /**
+   * Acquires the lock. If the lock is already held, waits until it's released.
+   * @returns A promise that resolves to a release function.
+   */
+  public async lock(): Promise<() => void> {
+    if (!this._locked) {
+      this._locked = true;
+      return () => this.unlock();
+    }
+
+    return new Promise((resolve) => {
+      this._waitQueue.push(() => {
+        resolve(() => this.unlock());
+      });
+    });
+  }
+
+  private unlock(): void {
+    const next = this._waitQueue.shift();
+    if (next) {
+      next();
+    } else {
+      this._locked = false;
+    }
+  }
+}

